function mulberry32(a: number) {
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
type Rnd = () => number;
const pickInt = (rnd: Rnd, lo: number, hi: number) => lo + Math.floor(rnd() * (hi - lo + 1));
function shuffled<T>(rnd: Rnd, xs: T[]): T[] {
  const a = xs.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rnd() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}
/** Suits for n distinct ranks: two clean two-card suits, or as few suited cards as n allows. */
function suitsFor(rnd: Rnd, n: number, doubleSuited: boolean): CardSuit[] {
  const s = shuffled(rnd, SUITS);
  const pattern = doubleSuited
    ? n === 4
      ? [s[0], s[0], s[1], s[1]]
      : [s[0], s[0], s[1], s[1], s[2]]
    : n === 4
      ? [s[0], s[1], s[2], s[3]]
      : [s[0], s[1], s[2], s[3], s[3]];
  return shuffled(rnd, pattern);
}
const deal = (rnd: Rnd, ranks: number[], doubleSuited: boolean): Card[] => {
  const suits = suitsFor(rnd, ranks.length, doubleSuited);
  return ranks.map((r, k) => ({ rank: RANK[r], suit: suits[k] }));
};
/** All n cards in one connected group: neighbours one apart, `gaps` of them two apart. */
function oneGroup(rnd: Rnd, n: number, doubleSuited: boolean): Card[] {
  const gaps = pickInt(rnd, 0, COORDINATED_MAX_GAPS[n]);
  const steps = shuffled(rnd, [
    ...Array.from({ length: gaps }, () => 2),
    ...Array.from({ length: n - 1 - gaps }, () => 1),
  ]);
  const width = steps.reduce((a, b) => a + b, 0);
  const ranks = [pickInt(rnd, 2, 14 - width)];
  for (const s of steps) ranks.push(ranks[ranks.length - 1] + s);
  return deal(rnd, ranks, doubleSuited);
}
/** Two high cards (ace, king or queen) over a low connected group, at least three ranks between them. */
function splitHighLow(rnd: Rnd, n: number, doubleSuited: boolean): Card[] {
  const high = shuffled(rnd, [14, 13, 12]).slice(0, 2);
  const lowTop = pickInt(rnd, n + 1, Math.min(...high) - 4);
  const low = Array.from({ length: n - 2 }, (_, k) => lowTop - k);
  return deal(rnd, [...high, ...low], doubleSuited);
}
/** Ace-king, ace-queen, ace-jack, king-queen or king-jack with unconnected low side cards. */
function bigCardsWithDanglers(rnd: Rnd, n: number, doubleSuited: boolean): Card[] {
  const big = shuffled(rnd, [
    [14, 13],
    [14, 12],
    [14, 11],
    [13, 12],
    [13, 11],
  ])[0];
  const side = shuffled(rnd, [2, 4, 6, 7].length ? [3, 5, 7] : []).slice(0, n - 2);
  const extra = n - 2 - side.length > 0 ? [2] : [];
  return deal(rnd, [...big, ...side, ...extra], doubleSuited);
}
const CLASS_N = 500;
const FOUR_BET_N = 100;
function census(
  make: (rnd: Rnd, n: number, ds: boolean) => Card[],
  n: number,
  ds: boolean,
  seed: number
) {
  const rnd = mulberry32(seed);
  return Array.from({ length: CLASS_N }, () => make(rnd, n, ds));
}
const share = (xs: boolean[]) => xs.filter(Boolean).length / xs.length;
const mean = (xs: number[]) => xs.reduce((a, b) => a + b, 0) / xs.length;

const variantOf = (n: number) => (n === 5 ? 'plo5' : 'plo4');
/** A measured re-raiser at a 3-bet rate of 0.10, heads-up, hero's position as given, 5% rake. */
const pricing = (inPosition: boolean, raiserBehind: number) => ({
  rate: 0.1,
  opportunities: 100,
  rateSource: 'measured' as const,
  inPosition,
  othersIn: 0,
  raiserBehind,
  rakeFraction: 0.05,
  heroAlreadyRaised: false,
  heroInvested: 0,
});
/** The priced numbers alone, for a call the class cell keeps (the cell itself does not price a keep). */
const pricedAlone = (i: OmahaOopReraisedInput) =>
  omahaReraisedCallPriced(
    i.hole,
    i.dead,
    i.preflopRaises,
    Math.min(i.toCall, i.stack),
    i.pot,
    i.stack,
    i.priced!
  )!;
/** 100bb, blinds 1/2: a pot-sized 3-bet of a 7 open (17 to call into 34). */
const threeBet = (hole: Card[], outOfPosition: boolean): OmahaOopReraisedInput => ({
  variant: variantOf(hole.length),
  hole,
  dead: [],
  outOfPosition,
  priced: pricing(!outOfPosition, 193),
  preflopRaises: 2,
  toCall: 17,
  stack: 193,
  pot: 34,
  band: null,
  hiLo: false,
  multiBoard: false,
  bombPot: false,
  tournament: false,
  allInOrFold: false,
});
/** 200bb: hero's pot 3-bet to 24 is 4-bet to 75 (51 to call into 102, 376 behind). */
const fourBet = (hole: Card[], outOfPosition: boolean): OmahaOopReraisedInput => ({
  ...threeBet(hole, outOfPosition),
  preflopRaises: 3,
  toCall: 51,
  stack: 376,
  pot: 102,
  priced: pricing(!outOfPosition, 376),
});

describe('coordination, by class (seeded census, 500 hands a class)', () => {
  for (const n of [4, 5])
    for (const ds of [true, false]) {
      const tag = `${variantOf(n)} ${ds ? 'double suited' : 'least suited'}`;
      it(`${tag}: every one-group hand is coordinated; no split or big-card-dangler hand is`, () => {
        const group = census(oneGroup, n, ds, 1100 + n + (ds ? 50 : 0));
        const split = census(splitHighLow, n, ds, 2100 + n + (ds ? 50 : 0));
        const dangler = census(bigCardsWithDanglers, n, ds, 3100 + n + (ds ? 50 : 0));
        expect(share(group.map((h) => omahaOopCoordinated(h) !== null))).toBe(1);
        expect(share(split.map((h) => omahaOopCoordinated(h) !== null))).toBe(0);
        expect(share(dangler.map((h) => omahaOopCoordinated(h) !== null))).toBe(0);
      });
    }
});

describe('the class cell, by class (the rule as on main; PLO4/PLO5 folds then go to the priced test)', () => {
  const stats: Record<
    string,
    { kept3: number; kept4o: number; kept4i: number; eq3: number; eq4: number }
  > = {};
  const run = (name: string, hands: Card[][]) => {
    const v3 = hands.map((h) => omahaOopReraisedClassCell(threeBet(h, true))!);
    // the 4-bet cells sample the rare declared 4-bet range: a slice of the class
    const few = hands.slice(0, FOUR_BET_N);
    const v4o = few.map((h) => omahaOopReraisedClassCell(fourBet(h, true))!);
    const v4i = few.map((h) => omahaOopReraisedClassCell(fourBet(h, false))!);
    stats[name] = {
      kept3: share(v3.map((v) => !v.fold)),
      kept4o: share(v4o.map((v) => !v.fold)),
      kept4i: share(v4i.map((v) => !v.fold)),
      eq3: mean(v3.map((v) => v.equity ?? 0)),
      eq4: mean(v4o.map((v) => v.equity ?? 0)),
    };
    return { v3, v4o, v4i };
  };
  it('uncoordinated classes never call a 3-bet out of position or a 4-bet in either position', () => {
    for (const n of [4, 5])
      for (const ds of [true, false])
        for (const [name, make] of [
          ['split', splitHighLow],
          ['dangler', bigCardsWithDanglers],
        ] as const) {
          const r = run(
            `${variantOf(n)} ${name} ${ds ? 'ds' : 'ls'}`,
            census(make, n, ds, 4100 + n + (ds ? 50 : 0))
          );
          for (const v of [...r.v3, ...r.v4o, ...r.v4i])
            expect([v.fold, v.reason]).toEqual([true, 'uncoordinated']);
        }
  });
  it('one-group hands: kept shares and equities (bounds stated)', () => {
    for (const n of [4, 5])
      for (const ds of [true, false])
        run(
          `${variantOf(n)} group ${ds ? 'ds' : 'ls'}`,
          census(oneGroup, n, ds, 5100 + n + (ds ? 50 : 0))
        );
    // Measured 2026-11-15 (500 hands a class; 100 for the 4-bet cells): double suited
    // 0.83 kept facing a 3-bet out of position in both games; least suited 0.39 (PLO4)
    // and 0.65 (PLO5); facing a 4-bet out of position 0.34 / 0.63 double suited and
    // 0.00 / 0.36 least suited; in position 0.78 / 0.96 and 0.21 / 0.85.
    for (const v of ['plo4', 'plo5']) {
      const dsS = stats[`${v} group ds`];
      const lsS = stats[`${v} group ls`];
      expect(dsS.kept3).toBeGreaterThanOrEqual(0.75);
      expect(dsS.kept3).toBeLessThan(1);
      expect(lsS.kept3).toBeLessThan(dsS.kept3);
      expect(dsS.eq3).toBeGreaterThan(lsS.eq3);
      expect(dsS.eq4).toBeGreaterThan(lsS.eq4);
      // out of position is the stricter test
      expect(dsS.kept4o).toBeLessThan(dsS.kept4i);
      expect(lsS.kept4o).toBeLessThanOrEqual(lsS.kept4i);
      expect(dsS.kept4o).toBeGreaterThanOrEqual(lsS.kept4o);
    }
  });
});

/**
 * The cell the decision uses, on the first 50 hands of each census class,
 * facing the 3-bet out of position and the 4-bet out of and in position
 * (150 calls a class; the re-raiser measured at 0.10, heads-up, 5% rake).
 * Per class: [folds facing the 3-bet, the 4-bet out of position, the 4-bet in
 * position, calls the class cell keeps, of those with EV(call) < 0].
 * The sampler is seeded by the cards, so the counts are exact.
 */
const CENSUS_PIN: Record<string, number[]> = {
  'plo4 split ds': [5, 2, 0, 0, 0],
  'plo4 dangler ds': [18, 5, 0, 0, 0],
  'plo4 group ds': [9, 11, 0, 96, 21],
  'plo4 split ls': [43, 24, 2, 0, 0],
  'plo4 dangler ls': [48, 41, 6, 0, 0],
  'plo4 group ls': [32, 40, 11, 29, 14],
  'plo5 split ds': [12, 3, 0, 0, 0],
  'plo5 dangler ds': [17, 4, 0, 0, 0],
  'plo5 group ds': [14, 8, 0, 119, 21],
  'plo5 split ls': [39, 18, 0, 0, 0],
  'plo5 dangler ls': [43, 27, 0, 0, 0],
  'plo5 group ls': [15, 20, 2, 93, 31],
};
describe('PLO4/PLO5: the pricing only overturns class folds (census, pinned counts)', () => {
  it('a class keep is returned as the class cell gave it, whatever its EV; a class fold stands only with EV(call) < 0', () => {
    const got: Record<string, number[]> = {};
    for (const n of [4, 5])
      for (const ds of [true, false])
        for (const [name, make, seed] of [
          ['split', splitHighLow, 4100],
          ['dangler', bigCardsWithDanglers, 4100],
          ['group', oneGroup, 5100],
        ] as const) {
          const hands = census(make, n, ds, seed + n + (ds ? 50 : 0)).slice(0, 50);
          const row = [0, 0, 0, 0, 0];
          [
            (h: Card[]) => threeBet(h, true),
            (h: Card[]) => fourBet(h, true),
            (h: Card[]) => fourBet(h, false),
          ].forEach((input, k) => {
            for (const h of hands) {
              const cls = omahaOopReraisedClassCell(input(h))!;
              const v = omahaOopReraisedCallCell(input(h))!;
              if (!cls.fold) {
                // kept by the class cell: never folded, main's verdict exactly, not priced
                expect(v).toEqual(cls);
                expect('pricing' in v).toBe(false);
                row[3]++;
                if (pricedAlone(input(h)).evCall < 0) row[4]++;
              } else {
                expect(v.pricing).toBeDefined();
                expect(v.classReason).toBe(cls.reason);
                expect([v.fold, v.reason]).toEqual(
                  v.pricing!.evCall < 0 ? [true, 'priced_fold'] : [false, 'priced_call']
                );
                expect(v.equity).toBe(v.pricing!.equity);
              }
              if (v.fold) row[k]++;
            }
          });
          got[`${variantOf(n)} ${name} ${ds ? 'ds' : 'ls'}`] = row;
        }
    expect(got).toEqual(CENSUS_PIN);
    // the protection is exercised: class keeps with a negative priced EV exist in every one-group class
    for (const k of Object.keys(got).filter((x) => x.includes('group')))
      expect(got[k][4]).toBeGreaterThan(0);
  });
});

describe('against the declared 4-bet range: equity by class (the unblocked preference)', () => {
  it('one-group hands without an ace or king, with one, and the uncoordinated classes', async () => {
    const { omahaReraisedEquity, omahaReraisedPremium } =
      await import('./HorseOmahaReraisedPot.js');
    const eq = (hands: Card[][]) =>
      mean(
        hands.map((h) => omahaReraisedEquity(h, [], [], (o) => omahaReraisedPremium(o), 300) ?? 0)
      );
    const keyCards = (h: Card[]) => h.filter((c) => c.rank === 'A' || c.rank === 'K').length;
    const out: Record<string, number> = {};
    for (const n of [4, 5]) {
      const group = census(oneGroup, n, true, 6100 + n);
      out[`${variantOf(n)} group ds, no ace or king`] = eq(
        group.filter((h) => keyCards(h) === 0).slice(0, 80)
      );
      out[`${variantOf(n)} group ds, one ace or king`] = eq(
        group.filter((h) => keyCards(h) === 1).slice(0, 80)
      );
      out[`${variantOf(n)} split ds`] = eq(census(splitHighLow, n, true, 6200 + n).slice(0, 80));
      out[`${variantOf(n)} dangler ds`] = eq(
        census(bigCardsWithDanglers, n, true, 6300 + n).slice(0, 80)
      );
    }
    // Measured 2026-11-15. PLO4 orders as the owner describes: live one-group hands
    // 0.424, one-group with one ace or king 0.402, split 0.397, big cards with danglers
    // 0.382. PLO5 does NOT: 0.449, 0.474, 0.466, 0.450. Raw all-in equity does not carry
    // the preference in PLO5, which is why the rule is the coordination test plus the
    // key-card margin and not equity alone.
    const g = (k: string) => out[k];
    expect(g('plo4 group ds, no ace or king')).toBeGreaterThan(g('plo4 group ds, one ace or king'));
    expect(g('plo4 group ds, one ace or king')).toBeGreaterThan(g('plo4 split ds'));
    expect(g('plo4 split ds')).toBeGreaterThan(g('plo4 dangler ds'));
    for (const k of Object.keys(out).filter((x) => x.startsWith('plo5'))) {
      expect(g(k)).toBeGreaterThan(0.42);
      expect(g(k)).toBeLessThan(0.5);
    }
  });
});

